CREATE TABLE `content_page_metrics` (
  `id` char(36) NOT NULL,
  `tenant_id` char(36) NOT NULL,
  `channel_id` char(36) DEFAULT NULL,
  `platform` varchar(50) NOT NULL,
  `page_id` varchar(255) NOT NULL,
  `metric_date` date NOT NULL,
  `metric_name` varchar(100) NOT NULL,
  `metric_value` bigint(20) DEFAULT NULL,
  `period` varchar(30) NOT NULL DEFAULT 'day',
  `grain` varchar(30) NOT NULL DEFAULT 'page',
  `availability` varchar(30) NOT NULL DEFAULT 'available',
  `warning` varchar(500) DEFAULT NULL,
  `fetched_at` datetime NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_page_metric_point` (`tenant_id`,`channel_id`,`platform`,`page_id`,`metric_date`,`metric_name`,`period`),
  KEY `idx_page_metrics_range` (`tenant_id`,`channel_id`,`platform`,`metric_date`),
  KEY `idx_page_metrics_name` (`tenant_id`,`metric_name`,`metric_date`),
  KEY `fk_cpgm_channel` (`channel_id`),
  CONSTRAINT `fk_cpgm_channel` FOREIGN KEY (`channel_id`) REFERENCES `publish_channels` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
